import { useEffect, useState } from "react";
import DashboardLayout from "../../layouts/DashboardLayout";
import { Bar } from "react-chartjs-2";
import { fetchStudentProgress, fetchCourseProgress } from "../../api";

export default function Reports() {
  const [studentData, setStudentData] = useState([]);
  const [courseData, setCourseData] = useState([]);

  useEffect(() => {
    const fetchReports = async () => {
      try {
        const studentsRes = await fetchStudentProgress();
        setStudentData(studentsRes.data);

        const coursesRes = await fetchCourseProgress();
        setCourseData(coursesRes.data);
      } catch (err) {
        console.error("Error fetching reports:", err);
      }
    };
    fetchReports();
  }, []);

  return (
    <DashboardLayout role="admin">
      <h2>Reports & Analytics</h2>

      <h3>Student-wise Completion</h3>
      <table border="1" cellPadding="8">
        <thead>
          <tr>
            <th>Student</th>
            <th>Total Lessons</th>
            <th>Completed</th>
            <th>Completion %</th>
            <th>Time Spent (mins)</th>
          </tr>
        </thead>
        <tbody>
          {studentData.map(s => (
            <tr key={s.id}>
              <td>{s.name}</td>
              <td>{s.totalLessons}</td>
              <td>{s.completedLessons}</td>
              <td>{s.completion}%</td>
              <td>{Math.floor(s.timeSpent / 60)}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h3>Course-wise Completion</h3>
      {courseData.map(c => (
        <div key={c.courseId} style={{ marginBottom: "30px" }}>
          <h4>{c.courseName}</h4>
          <Bar
            data={{
              labels: c.studentsProgress.map(sp => sp.studentName),
              datasets: [
                {
                  label: "% Completion",
                  data: c.studentsProgress.map(sp => sp.completion),
                  backgroundColor: "rgba(75,192,192,0.6)"
                }
              ]
            }}
            options={{ responsive: true, plugins: { legend: { display: true } } }}
          />
        </div>
      ))}
    </DashboardLayout>
  );
}
